package com.gr4nt.filexplorer;
import java.io.*;import java.nio.*;import java.nio.charset.*;import java.security.*;import java.util.*;
public final class BinaryTools {
 public static String hex(byte[] data){StringBuilder b=new StringBuilder();for(int i=0;i<data.length;i+=16){b.append(String.format(Locale.ROOT,"%08x  ",i));for(int j=0;j<16;j++)b.append(i+j<data.length?String.format("%02X ",data[i+j]&255):"   ");b.append("  ");for(int j=0;j<16&&i+j<data.length;j++){int c=data[i+j]&255;b.append(c>=32&&c<127?(char)c:'.');}b.append('\n');}return b.toString();}
 public static byte[] unhex(String s)throws IOException{String raw=s.replaceAll("\\s","");if((raw.length()&1)!=0||!raw.matches("[0-9a-fA-F]*"))throw new IOException("Enter complete hexadecimal byte pairs");byte[] out=new byte[raw.length()/2];for(int i=0;i<out.length;i++)out[i]=(byte)Integer.parseInt(raw.substring(i*2,i*2+2),16);return out;}
 public static String hashes(InputStream input)throws IOException{try{MessageDigest sha=MessageDigest.getInstance("SHA-256"),md5=MessageDigest.getInstance("MD5");byte[] buf=new byte[65536];int n;while((n=input.read(buf))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();sha.update(buf,0,n);md5.update(buf,0,n);}return "SHA-256\n"+bytes(sha.digest())+"\n\nMD5\n"+bytes(md5.digest());}catch(NoSuchAlgorithmException e){throw new IOException(e);}}
 static String bytes(byte[] a){StringBuilder s=new StringBuilder();for(byte b:a)s.append(String.format("%02x",b));return s.toString();}
 static String escape(String s){return s.replace("&","&amp;").replace("<","&lt;").replace("\"","&quot;");}
 public static String binaryXml(byte[] data)throws IOException{
  try{ByteBuffer b=ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN);if(data.length<8||(b.getShort(0)&65535)!=3)throw new IOException("Not Android binary XML");List<String> strings=new ArrayList<>();StringBuilder out=new StringBuilder("<?xml version=\"1.0\" encoding=\"utf-8\"?>\n");int depth=0;
   for(int p=8;p+8<=data.length;){int type=b.getShort(p)&65535,header=b.getShort(p+2)&65535,size=b.getInt(p+4);if(size<8||p+size>data.length)throw new IOException("Invalid AXML chunk");
    if(type==1){int count=b.getInt(p+8),flags=b.getInt(p+16),start=b.getInt(p+20);if(count<0||count>100000)throw new IOException("Invalid string pool");for(int i=0;i<count;i++){int q=p+start+b.getInt(p+header+i*4);boolean utf8=(flags&256)!=0;int[] at={q};if(utf8){length8(data,at);int len=length8(data,at);strings.add(new String(data,at[0],len,StandardCharsets.UTF_8));}else{int len=b.getShort(at[0])&65535;at[0]+=2;if((len&0x8000)!=0){len=((len&0x7fff)<<16)|(b.getShort(at[0])&65535);at[0]+=2;}strings.add(new String(data,at[0],len*2,StandardCharsets.UTF_16LE));}}}
    else if(type==0x102){int ext=p+header,name=b.getInt(ext+4),attributes=b.getShort(ext+12)&65535,attributeStart=b.getShort(ext+8)&65535,attributeSize=b.getShort(ext+10)&65535;if(attributeSize<20)throw new IOException("Invalid attribute size");indent(out,depth++);out.append('<').append(str(strings,name));if(depth==1)out.append(" xmlns:android=\"http://schemas.android.com/apk/res/android\"");for(int i=0;i<attributes;i++){int a=ext+attributeStart+i*attributeSize;int ns=b.getInt(a),an=b.getInt(a+4),raw=b.getInt(a+8),vt=data[a+15]&255,val=b.getInt(a+16);out.append(' ');if(ns>=0&&str(strings,ns).contains("android"))out.append("android:");out.append(str(strings,an)).append("=\"").append(escape(raw>=0?str(strings,raw):value(strings,vt,val))).append('"');}out.append(">\n");}
    else if(type==0x103){indent(out,--depth);out.append("</").append(str(strings,b.getInt(p+header+4))).append(">\n");}p+=size;
   }return out.toString();
  }catch(IndexOutOfBoundsException|IllegalArgumentException e){throw new IOException("Malformed binary XML",e);}
 }
 static String value(List<String> s,int t,int v){if(t==3)return str(s,v);if(t==18)return v!=0?"true":"false";if(t==16)return String.valueOf(v);if(t==1)return String.format("@0x%08x",v);if(t==2)return String.format("?0x%08x",v);if(t==4)return String.valueOf(Float.intBitsToFloat(v));return String.format("0x%08x",v);}
 static int length8(byte[] d,int[] p){int a=d[p[0]++]&255;return (a&128)!=0?((a&127)<<8)|(d[p[0]++]&255):a;}
 static String str(List<String> s,int n){return n>=0&&n<s.size()?s.get(n):"unknown";}static void indent(StringBuilder s,int n){for(int i=0;i<Math.max(0,n);i++)s.append("  ");}
}
